export const SUPABASE_URL = (import.meta as any).env?.VITE_SUPABASE_URL || 'https://btwerbixrydfalqrpnmg.supabase.co';
export const SUPABASE_ANON_KEY = (import.meta as any).env?.VITE_SUPABASE_ANON_KEY || '';

